package com.campuskart; import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import javax.servlet.*;import java.io.*;import java.sql.*;import java.util.*; @WebServlet("/my-listings") public class MyListingsServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.jsp");return;}CleanupUtil.removeExpiredSoldListings();List<Map<String,Object>> items=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,name,price,category,item_condition,item_age,description,status,sold_at FROM products WHERE seller_id=? ORDER BY created_at DESC")){p.setInt(1,(Integer)h.getAttribute("userId"));try(ResultSet x=p.executeQuery()){while(x.next()){Map<String,Object> m=new HashMap<>();for(String k:new String[]{"id","name","price","category","item_condition","item_age","description","status","sold_at"})m.put(k,x.getObject(k));items.add(m);}}}catch(SQLException e){throw new ServletException(e);}r.setAttribute("products",items);r.getRequestDispatcher("/my-listings.jsp").forward(r,s);}}